#!/usr/bin/env bash
set -euo pipefail
umask 077
[[ "${1:-}" == --source-context && -n "${2:-}" && "${3:-}" == --kind && "${4:-}" =~ ^(sbom|trivy)$ && "${5:-}" == --release-manifest && -n "${6:-}" && $# == 6 ]] || { echo 'Usage: run-internal-ci-image-scan.sh --source-context <context> --kind <sbom|trivy> --release-manifest <manifest>' >&2; exit 64; }
context=$2; kind=$4; manifest=$6; workspace=$PWD; artifact_root=$(realpath -e "$workspace/.release/internal-ci/${CI_COMMIT_SHA:?}"); source_root="${RUNNER_TEMP:?}/lunchlineup-source-${CI_RUN_ID:?}"; build_root="$source_root/build"; temporary="$RUNNER_TEMP/lunchlineup-$kind-$CI_RUN_ID"; output="$artifact_root/$kind"; cache="$RUNNER_TEMP/lunchlineup-trivy-cache-$CI_RUN_ID"; test ! -e "$temporary"; test ! -e "$output"; mkdir -m 0700 -p "$temporary" "$output"; [[ "$kind" != trivy || ! -e "$cache" ]] || { test -d "$cache" && test ! -L "$cache"; }; [[ "$kind" != trivy ]] || mkdir -m 0700 -p "$cache"; trap 'rm -rf -- "$temporary"' EXIT
SYFT_IMAGE='anchore/syft:v1.38.0-nonroot@sha256:86e3e28b85481f2a17d6bbc3f436a7d5a1fb4f6e9227ec4c22f70b2e710f7339'; TRIVY_IMAGE='aquasec/trivy:0.69.3@sha256:bcc376de8d77cfe086a917230e818dc9f8528e3c852f7b1aff648949b6258d1c'
node -e 'const fs=require("node:fs"),path=require("node:path"),root=fs.realpathSync(process.argv[2]),x=JSON.parse(fs.readFileSync(process.argv[1]));for(const [n,v] of Object.entries(x.images??{})){const rel=v.archive?.path;if(!/^[a-z0-9][a-z0-9._/-]*$/.test(rel??"")||path.isAbsolute(rel)||rel.split("/").includes(".."))throw new Error(`Unsafe release archive path: ${n}`);const candidate=path.resolve(root,rel),real=fs.realpathSync(candidate),boundary=root.endsWith(path.sep)?root:root+path.sep,stat=fs.lstatSync(candidate);if(!real.startsWith(boundary)||stat.isSymbolicLink()||!stat.isFile())throw new Error(`Release archive escapes artifact root: ${n}`);console.log([n,rel,v.archive.sha256,v.archive.bytes].join("\t"));}' "$manifest" "$artifact_root" | while IFS=$'\t' read -r name archive_relative expected_sha expected_bytes; do archive="$artifact_root/$archive_relative"; [[ "$(sha256sum "$archive"|awk '{print $1}')" == "$expected_sha" && "$(stat -c %s "$archive")" == "$expected_bytes" ]] || { echo "Release archive mismatch: $name" >&2; exit 1; }; gzip -dc "$archive" >"$temporary/$name.tar"; if [[ "$kind" == sbom ]]; then docker run --rm --user 0:0 -v "$temporary/$name.tar:/image.tar:ro" -v "$output:/out:rw" "$SYFT_IMAGE" docker-archive:/image.tar -o "spdx-json=/out/$name.spdx.json"; chmod 0600 "$output/$name.spdx.json"; else docker run --rm --user 0:0 -v "$temporary/$name.tar:/image.tar:ro" -v "$build_root/.trivyignore.yaml:/workspace/.trivyignore.yaml:ro" -v "$cache:/root/.cache/trivy:rw" -v "$output:/out:rw" "$TRIVY_IMAGE" image --input /image.tar --format json --output "/out/$name.trivy.json" --scanners vuln --severity HIGH,CRITICAL --ignorefile /workspace/.trivyignore.yaml --exit-code 1; chmod 0600 "$output/$name.trivy.json"; fi; rm -f "$temporary/$name.tar"; done
node "$build_root/scripts/verify-internal-ci-image-reports.mjs" --source-context "$context" --kind "$kind" --release-manifest "$manifest" --report-directory "$output" --scanner-image "$([[ "$kind" == sbom ]] && printf '%s' "$SYFT_IMAGE" || printf '%s' "$TRIVY_IMAGE")" --output "$output/summary.json" --details "$artifact_root/details/$kind.json"
